// =========================
//  DATABASE CONNECTION
// =========================
$pdo = new PDO(
	"mysql:host=localhost;dbname=asterisk;charset=utf8mb4",
	"cron",
	"1234",
	[PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]
);
$user_param = $_GET['user'] ?? '';
$user_group_param = $_GET['user_group'] ?? '';

//echo "user group: $user_group_param";
// =========================
//  READ FILTER INPUTS
// =========================
$start_date = $_GET['start_date'] ?? date('Y-m-d 00:00:00');
$end_date = $_GET['end_date'] ?? date('Y-m-d 23:59:59');
$phone = $_GET['phone'] ?? '';
$page = isset($_GET['page']) ? max(1, (int) $_GET['page']) : 1;
$limit = 20;

// =========================
//  MAIN QUERY (WITH address1 + user_group filter)
// =========================
$sql = "SELECT
            vl.call_date,
            vl.phone_number,
            vl.status,
            vl.user,
            vl.campaign_id,
            vl.list_id,
            vl.lead_id,
            vlist.address1
        FROM vicidial_log vl
        LEFT JOIN vicidial_list vlist ON vl.lead_id = vlist.lead_id
        LEFT JOIN vicidial_users vu ON vu.user = vl.user
        WHERE vl.call_date BETWEEN :start_date AND :end_date
        AND vl.status = 'SALE' ";

// ------ Optional user_group filter ------
if (!empty($user_group_param)) {
	$sql .= " AND vu.user_group = :user_group ";
}

// ------ Optional phone filter ------
if (!empty($phone)) {
	$sql .= " AND vl.phone_number LIKE :phone ";
}

$stmt = $pdo->prepare($sql);
$stmt->bindValue(':start_date', $start_date);
$stmt->bindValue(':end_date', $end_date);
if (!empty($user_group_param)) {
	$stmt->bindValue(':user_group', $user_group_param);
}
if (!empty($phone))
	$stmt->bindValue(':phone', "%$phone%");
$stmt->execute();
$rows = $stmt->fetchAll(PDO::FETCH_ASSOC);

// =========================
//  CHART SUMMARY (SALE Count by Campaign)
// =========================
$campaignCounts = [];
foreach ($rows as $r) {
	$cid = $r['campaign_id'];
	$campaignCounts[$cid] = ($campaignCounts[$cid] ?? 0) + 1;
}

