	##### BEGIN log visit to the vicidial_report_log table #####
	$LOGip = getenv("REMOTE_ADDR");
	$LOGbrowser = getenv("HTTP_USER_AGENT");
	$LOGscript_name = getenv("SCRIPT_NAME");
	$LOGserver_name = getenv("SERVER_NAME");
	$LOGserver_port = getenv("SERVER_PORT");
	$LOGrequest_uri = getenv("REQUEST_URI");
	$LOGhttp_referer = getenv("HTTP_REFERER");
	$LOGbrowser = preg_replace("/\'|\"|\\\\|<|>/", "", $LOGbrowser);
	$LOGrequest_uri = preg_replace("/\'|\"|\\\\|<|>/", "", $LOGrequest_uri);
	$LOGhttp_referer = preg_replace("/\'|\"|\\\\|<|>/", "", $LOGhttp_referer);
	if (preg_match("/443/i", $LOGserver_port)) {
		$HTTPprotocol = 'https://';
	} else {
		$HTTPprotocol = 'http://';
	}
	if (($LOGserver_port == '80') or ($LOGserver_port == '443')) {
		$LOGserver_port = '';
	} else {
		$LOGserver_port = ":$LOGserver_port";
	}
	$LOGfull_url = "$HTTPprotocol$LOGserver_name$LOGserver_port$LOGrequest_uri";

	$LOGhostname = php_uname('n');
	if (strlen($LOGhostname) < 1) {
		$LOGhostname = 'X';
	}
	if (strlen($LOGserver_name) < 1) {
		$LOGserver_name = 'X';
	}

	$stmt = "SELECT webserver_id FROM vicidial_webservers where webserver='$LOGserver_name' and hostname='$LOGhostname' LIMIT 1;";
	if ($DB) {
		echo "$stmt\n";
	}
	$rslt = mysql_to_mysqli($stmt, $link);
	$webserver_id_ct = mysqli_num_rows($rslt);
	if ($webserver_id_ct > 0) {
		$row = mysqli_fetch_row($rslt);
		$webserver_id = $row[0];
	} else {
		##### insert webserver entry
		$stmt = "INSERT INTO vicidial_webservers (webserver,hostname) values('$LOGserver_name','$LOGhostname');";
		if ($DB) {
			echo "$stmt\n";
		}
		$rslt = mysql_to_mysqli($stmt, $link);
		$affected_rows = mysqli_affected_rows($link);
		$webserver_id = mysqli_insert_id($link);
	}

	$stmt = "INSERT INTO vicidial_report_log set event_date=NOW(), user='$PHP_AUTH_USER', ip_address='$LOGip', report_name='$report_name', browser='$LOGbrowser', referer='$LOGhttp_referer', notes='$LOGserver_name:$LOGserver_port $LOGscript_name |$group, $query_date, $end_date, $shift, $stage, $report_display_type|', url='$LOGfull_url', webserver='$webserver_id';";
	$rslt = mysql_to_mysqli($stmt, $link);
	$report_log_id = mysqli_insert_id($link);
	if ($DB) {
		echo "$report_log_id|$stmt|\n";
	}
	##### END log visit to the vicidial_report_log table #####
