if ($ADD == 73) {
	if ($LOGmodify_campaigns == 1) {
		echo "<div class='did_main'>\n";

		$stmt = "SELECT dial_statuses,local_call_time,lead_filter_id,drop_lockout_time,call_count_limit from vicidial_campaigns where campaign_id='$campaign_id' $LOGallowed_campaignsSQL;";
		$rslt = mysql_to_mysqli($stmt, $link);
		$row = mysqli_fetch_row($rslt);
		$dial_statuses = $row[0];
		$local_call_time = $row[1];
		$drop_lockout_time = $row[3];
		$call_count_limit = $row[4];
		if ($lead_filter_id == '') {
			$lead_filter_id = $row[2];
			if ($lead_filter_id == '') {
				$lead_filter_id = 'NONE';
			}
		}

		$stmt = "SELECT list_id,active,list_name from vicidial_lists where campaign_id='$campaign_id' $LOGallowed_campaignsSQL;";
		$rslt = mysql_to_mysqli($stmt, $link);
		$lists_to_print = mysqli_num_rows($rslt);
		$camp_lists = '';
		$o = 0;
		while ($lists_to_print > $o) {
			$rowx = mysqli_fetch_row($rslt);
			$o++;
			if (preg_match('/Y/', $rowx[1])) {
				$camp_lists .= "'$rowx[0]',";
			}
		}
		$camp_lists = preg_replace('/.$/i', '', $camp_lists);

		$filterSQL = $filtersql_list[$lead_filter_id];
		$filterSQL = preg_replace("/\\\\/", "", $filterSQL);
		$filterSQL = preg_replace('/^and|and$|^or|or$/i', '', $filterSQL);
		if (strlen($filterSQL) > 4) {
			$fSQL = "and ($filterSQL)";
		} else {
			$fSQL = '';
		}


		echo "<div class='show_disable'>\n";
		echo "<div class='inner_cap'><b>" . _QXZ("Show Dialable Leads Count") . "</B> - </div>\n";
		echo "<div class='inner_cap'><B>" . _QXZ("CAMPAIGN") . ":</B> $campaign_id </div>\n";
		echo "<div class='inner_cap'><B>" . _QXZ("LISTS") . ":</B> $camp_lists</div>\n";
		echo "<div class='inner_cap'><B>" . _QXZ("STATUSES") . ":</B> $dial_statuses</div>\n";
		echo "<div class='inner_cap'><B>" . _QXZ("FILTER") . ":</B> $lead_filter_id</div>\n";
		echo "<div class='inner_cap'><B>" . _QXZ("CALL LIMIT") . ":</B> $call_count_limit </div>\n";
		echo "<div class='inner_cap'><B>" . _QXZ("CALL TIME") . ":</B> $local_call_time</div>\n";
		echo "<div class='inner_cap'><B>" . _QXZ("With Filter") . ":</B></div>\n";


		### call function to calculate and print dialable leads
		$single_status = 0;
		$only_return = 0;
		dialable_leads($DB, $link, $local_call_time, $dial_statuses, $camp_lists, $drop_lockout_time, $call_count_limit, $single_status, $fSQL, $only_return);

		echo "<div class='inner_cap'>\n";
		echo "<B>" . _QXZ("Without Filter") . ":</B></div>\n";

		dialable_leads($DB, $link, $local_call_time, $dial_statuses, $camp_lists, $drop_lockout_time, $call_count_limit, $single_status, '', $only_return);

		echo "</div>\n";
		echo "</BODY></HTML>\n";

		exit;
		echo "</div>";
	} else {
		echo "<div class='error_popup'>" . _QXZ("You do not have permission to view this page") . "</div>\n";
