######################
# ADD=3211 areacode list modification screen
######################
if ($ADD == 3211) {
	if ($LOGmodify_ingroups == 1) {
		echo "<div style='display: flex; align-items: center; justify-content: space-between; margin-bottom:30px;'>";
		echo "<div class='agent_heading'><span>INBOUND GROUP</span> / Modify Areacode List</div>";
		echo "<div style='color:#63726E; font-size:10px;'>Home - Inbound Group - <span style='font-weight: bold; font-style: italic;'>Modify Areacode List</span></div>\n";
		echo "</div>";
		echo "<div class='did_main'>\n";

		$stmt = "SELECT count(*) FROM vicidial_inbound_groups where group_id='$group_id';";
		$rslt = mysql_to_mysqli($stmt, $link);
		$row = mysqli_fetch_row($rslt);
		$vig_exists = $row[0];

		if ($vig_exists > 0) {
			### read in all areacodes in this in-group areacode filter list
			$stmt = "SELECT areacode FROM vicidial_areacode_filters where group_id='$group_id' order by areacode;";
			$rslt = mysql_to_mysqli($stmt, $link);
			$vaf_ct = mysqli_num_rows($rslt);
			$vaf = 0;
			while ($vaf_ct > $vaf) {
				$row = mysqli_fetch_row($rslt);
				$vaf_list[$vaf] = $row[0];
				$vaf_count[$vaf] = 0;
				$vaf++;
			}

			if (strlen($areacode_list) > 2) {
				$PN = explode("\n", $areacode_list);
				$PNct = count($PN);
				$p = 0;
				$stmt_log = '';
				while ($p < $PNct) {
					if (strlen($PN[$p]) > 0) {
						$ac_found = 0;
						$vaf = 0;
						while ($vaf_ct > $vaf) {
							if ($PN[$p] == $vaf_list[$vaf]) {
								$vaf_count[$vaf]++;
								$ac_found++;
							}
							$vaf++;
						}
						if ($ac_found < 1) {
							$stmt = "SELECT count(*) from vicidial_areacode_filters where areacode='$PN[$p]' and group_id='$group_id';";
							$rslt = mysql_to_mysqli($stmt, $link);
							$row = mysqli_fetch_row($rslt);
							if ($row[0] < 1) {
								$stmt = "INSERT INTO vicidial_areacode_filters (areacode,group_id) values('$PN[$p]','$group_id');";
								$rslt = mysql_to_mysqli($stmt, $link);
								$stmt_log .= "$stmt|";
								if ($DB > 0) {
									echo "Added areacode $PN[$p]<br>\n";
								}
							} else {
								if ($DB > 0) {
									echo "Skipped add, already exists: $PN[$p]<br>\n";
								}
							}
						}
					}
					$p++;
				}

				$vaf = 0;
				while ($vaf_ct > $vaf) {
					if ($vaf_count[$vaf] < 1) {
						$stmt = "SELECT count(*) from vicidial_areacode_filters where areacode='$vaf_list[$vaf]' and group_id='$group_id';";
						$rslt = mysql_to_mysqli($stmt, $link);
						$row = mysqli_fetch_row($rslt);
						if ($row[0] > 0) {
							$stmt = "DELETE FROM vicidial_areacode_filters where areacode='$vaf_list[$vaf]' and group_id='$group_id';";
							$rslt = mysql_to_mysqli($stmt, $link);
							$stmt_log .= "$stmt|";
							if ($DB > 0) {
								echo "Removed areacode $vaf_list[$vaf]<br>\n";
							}
						} else {
							if ($DB > 0) {
								echo "Skipped delete, already removed: $vaf_list[$vaf]<br>\n";
							}
						}
					}
					$vaf++;
				}

				if (strlen($stmt_log) > 10) {
					### LOG INSERTION Admin Log Table ###
					$SQL_log = "$stmt_log|";
					$SQL_log = preg_replace('/;/', '', $SQL_log);
					$SQL_log = addslashes($SQL_log);
					$stmt = "INSERT INTO vicidial_admin_log set event_date='$SQLdate', user='$PHP_AUTH_USER', ip_address='$ip', event_section='INGROUPS', event_type='MODIFY', record_id='$group_id', event_code='ADMIN MODIFY AREACODE FILTER', event_sql=\"$SQL_log\", event_notes='';";
					if ($DB) {
						echo "|$stmt|\n";
					}
					$rslt = mysql_to_mysqli($stmt, $link);
				}
			}

			### read in all areacodes in this in-group areacode filter list
			$stmt = "SELECT areacode FROM vicidial_areacode_filters where group_id='$group_id' order by areacode;";
			$rslt = mysql_to_mysqli($stmt, $link);
			$vaf_ct = mysqli_num_rows($rslt);
			$vaf = 0;
			$vaf_textarea = '';
			while ($vaf_ct > $vaf) {
				$row = mysqli_fetch_row($rslt);
				$vaf_textarea .= "$row[0]\n";
				$vaf++;
			}

			echo "<div style='display:flex; gap:15px; align-items:center; margin-bottom: 30px;'>
				<h2>" . _QXZ("Modify Areacode List") . "</h2>
				<img src='images/edit-icon.png' style='height:52px;'/>
			</div>";

			echo "<form action=$PHP_SELF method=POST>\n";
			echo "<div class='inner_didi_main'>\n";
			echo "<input type=hidden name=ADD value=3211>\n";
			echo "<input type=hidden name=group_id value=\"$group_id\">\n";
			echo "<input type=hidden name=DB value=\"$DB\">\n";

			echo "<div class='did_label_input'><label style='width: 25%;'>" . _QXZ("In-Group") . ": </label><b>$group_id</b> &nbsp; <a href=\"$PHP_SELF?ADD=3111&group_id=$group_id\" style='color:#11c3b9; text-decoration:underline;'>" . _QXZ("modify") . "</a></div>\n";
			echo "<div class='did_label_input' style='align-items: baseline !important;'><label style='width: 25%;'>" . _QXZ("Areacodes") . ": <br><br><span style='font-size:11px; font-weight:normal;'>(" . _QXZ("one areacode per line only") . ")</span><BR>$NWB#internal_list-dnc$NWE</label><TEXTAREA name=areacode_list ROWS=15 COLS=10 style='width: 20%; background-color:#000; color:#fff; border: 1px solid #11c3b9; border-radius:5px; padding:10px;'>$vaf_textarea</TEXTAREA></div>\n";
			echo "</div>";
			echo "<div class='did_input_three' style='display: flex; justify-content: center; margin-top: 20px;'><input class='btn_submits' type=submit name=SUBMIT value='" . _QXZ("SUBMIT") . "'></div>\n";
			echo "</FORM>\n";
		} else {
			echo _QXZ("You must use a valid group") . "\n";
		}
		echo "</div>";
	} else {
		echo "<div class='error_popup'>" . _QXZ("You do not have permission to view this page") . "</div>\n";
		exit;
	}
}
