				$adl = 0;
				while ($adl <= $SSauto_dial_limit) {
					if ($adl < 1) {
						$adl = ($adl + 1);
					} else {
						if ($adl < 3) {
							$adl = ($adl + 0.1);
						} else {
							if ($adl < 4) {
								$adl = ($adl + 0.25);
							} else {
								if ($adl < 5) {
									$adl = ($adl + 0.5);
								} else {
									if ($adl < 20) {
										$adl = ($adl + 1);
									} else {
										if ($adl < 40) {
											$adl = ($adl + 2);
										} else {
