			echo "<h2 style='display:flex; align-items:center;' class='filter_head'>" . _QXZ("AREACODE CIDS FOR THIS CAMPAIGN") . ": &nbsp; $NWB#campaign_cid_areacodes$NWE</h2>\n";
			if ($use_custom_cid != 'AREACODE') {
				echo "<div style='color:red; margin:20px 0;' >" . _QXZ("The campaign setting Custom CallerID is not set to AREACODE") . "! </div>";
			}
			echo "<form action=$PHP_SELF method=POST>\n";
			echo "<input type=hidden name=ADD value=202>\n";
			echo "<input type=hidden name=stage value=MODIFY>\n";
			echo "<input type=hidden name=campaign_id value=\"$campaign_id\">\n";

			$stmt = "SELECT areacode,outbound_cid,active,cid_description,call_count_today from vicidial_campaign_cid_areacodes where campaign_id='$campaign_id' $LOGallowed_campaignsSQL order by areacode,outbound_cid;";
			$rslt = mysql_to_mysqli($stmt, $link);
			$accids_to_print = mysqli_num_rows($rslt);
			$o = 0;
			while ($accids_to_print > $o) {
				$rowx = mysqli_fetch_row($rslt);
				$Xareacode[$o] = $rowx[0];
				$Xoutbound_cid[$o] = $rowx[1];
				$Xactive[$o] = $rowx[2];
				$Xcid_description[$o] = $rowx[3];
				$Xcall_count_today[$o] = $rowx[4];
				$checkbox_list .= "|active_$Xareacode[$o]_$Xoutbound_cid[$o]";
				$o++;
				$checkbox_count++;
			}
			echo "<table class='table_inbound'><thead>";
			echo "<tr><td style='width:10%;'>#</td><td style='width:14%;'>" . _QXZ("AREACODE") . "</td><td style='width:14%;'>" . _QXZ("CID NUMBER") . "</td><td style='width:20%;'>" . _QXZ("DESCRIPTION") . "</td><td style='width:14%;'>" . _QXZ("ACTIVE") . "<br><span id=ACCID_link><a href=\"#\" onclick=\"FORM_selectall('$checkbox_count','$checkbox_list','on','ACCID_link');return false;\"><font size=1>" . _QXZ("select all") . "</font></a></span></td><td style='width:14%;'>" . _QXZ("CALLS") . "</td><td>" . _QXZ("DELETE") . "</td></tr><thead>\n";

			$o = 0;
			while ($accids_to_print > $o) {
				$ct = ($o + 1);
				if ($ct == '1') {
					$bgcolor = 'bgcolor="#' . $SSstd_row1_background . '"';
					$bgac = $Xareacode[$o];
				} else {
					if ($Xareacode[$o] != $bgac) {
						if (preg_match("/1$|3$|5$|7$|9$/i", $bgct)) {
							$bgcolor = 'bgcolor="#' . $SSstd_row1_background . '"';
						} else {
							$bgcolor = 'bgcolor="#' . $SSstd_row2_background . '"';
						}
						$bgct++;
						$bgac = $Xareacode[$o];
					}
				}

				$DID_edit_link_BEGIN = '';
				$DID_edit_link_END = '';
				if (strlen($Xoutbound_cid[$o]) > 0) {
					$stmt = "SELECT did_id from vicidial_inbound_dids where did_pattern='$Xoutbound_cid[$o]' $LOGadmin_viewable_groupsSQL limit 1;";
					$rslt = mysql_to_mysqli($stmt, $link);
					$dids_to_print = mysqli_num_rows($rslt);
					if ($dids_to_print > 0) {
						$rowx = mysqli_fetch_row($rslt);
						$DID_edit_link_BEGIN = "<a href=\"$PHP_SELF?ADD=3311&did_id=$rowx[0]\">";
						$DID_edit_link_END = '</a>';
					}
				}
