				$ARIG_ranked = preg_replace('/[^-0-9]/', '', $ARIG_ranked);
				$ARIG_graded = preg_replace('/[^-0-9]/', '', $ARIG_graded);
				$ARIG_limited = preg_replace('/[^-0-9]/', '', $ARIG_limited);

				$stmtA = '';
				$stmtB = '';
				$stmtC = '';
				$stmtD = '';
				$stmtE = '';
				$ARIG_updated = 0;
				$ARIG_changenotes = '';
