					$stmtD = "UPDATE vicidial_inbound_group_agents set group_grade='$ARIG_graded' where user='$ARIG_user[$o]' and group_id='$group_id';";
					$rslt = mysql_to_mysqli($stmtD, $link);
					if ($DB > 0) {
						echo "|$stmtD|";
					}
