			$dtlc_to_print = mysqli_num_rows($rslt);
			$pre_filter_recent_call_menu = '';
			$dtlc_selected = 0;
			$o = 0;
			while ($dtlc_to_print > $o) {
				$rowx = mysqli_fetch_row($rslt);
				if (mb_strlen($rowx[1], 'utf-8') > 40) {
					$rowx[1] = mb_substr($rowx[1], 0, 40, 'utf-8') . '...';
				}
				$pre_filter_recent_call_menu .= "<option ";
				if ($pre_filter_recent_call == "$rowx[0]") {
					$pre_filter_recent_call_menu .= "SELECTED ";
					$dtlc_selected++;
				}
				$pre_filter_recent_call_menu .= "value=\"$rowx[0]\">$rowx[0] - $rowx[1]</option>\n";
				$o++;
			}

			echo "<div class='did_label_input'><label style='width: 30%;'>";
			if ($dtlc_selected > 0) {
				echo "<a href=\"$PHP_SELF?ADD=392111111111&container_id=$pre_filter_recent_call\">" . _QXZ("Pre-Filter Recent Call") . "</a>";
			} else {
				echo _QXZ("Pre-Filter Recent Call");
			}
			echo ": </label><div class='custom-select' style='width:60%;'><select  size=1 name=pre_filter_recent_call><option value=''>" . _QXZ("DISABLED") . "</option>$pre_filter_recent_call_menu</select></div>$NWB#inbound_dids-pre_filter_recent_call$NWE</div>\n";

			echo "<div class='did_label_input'><label style='width: 30%;'>" . _QXZ("Pre-Filter Recent Call DID") . ": </label><input style='width: 60%;' type=text name=pre_filter_recent_extension size=40 maxlength=50 value=\"$pre_filter_recent_extension\">$NWB#inbound_dids-pre_filter_recent_extension$NWE</div>\n";

