			echo "<tr><td>" . _QXZ("USER") . "</td><td>" . _QXZ("FULL NAME") . "</td><td>" . _QXZ("LEVEL") . "</td><td>" . _QXZ("ACTIVE") . "</td><td>" . _QXZ("USER GROUP") . "</td></tr>\n";

			$o = 0;
			while ($users_to_print > $o) {
				$rowx = mysqli_fetch_row($rsltx);
				$o++;

				if (preg_match('/1$|3$|5$|7$|9$/i', $o)) {
					$bgcolor = 'bgcolor="#' . $SSstd_row1_background . '"';
				} else {
					$bgcolor = 'bgcolor="#' . $SSstd_row2_background . '"';
				}

				echo "<tr $bgcolor>\n";
				echo "<td><a href=\"$PHP_SELF?ADD=3&user=$rowx[0]\">$rowx[0]</a></td>\n";
				echo "<td>$rowx[1]</td>\n";
				echo "<td>$rowx[2]</td>\n";
				echo "<td>" . _QXZ("$rowx[3]") . "</td>\n";
				echo "<td>$rowx[4]</td>\n";
				echo "</tr>\n";
			}
			if ($o < 1) {
				echo "<tr bgcolor=\"#" . $SSstd_row1_background . "\"><td colspan=5>--" . _QXZ("NONE") . "--</td></tr>\n";
			}

			echo "</table></div>\n";






			echo "<a href=\"$PHP_SELF?ADD=8111&user_group=$user_group\" style='display:none;'>" . _QXZ("Click here to see all CallBack Holds in this user group") . "</a>\n";
			echo "<a href=\"./timeclock_status.php?user_group=$user_group\" style='display:none;'>" . _QXZ("Click here to see the Timeclock Status for this user group") . "</a>\n";

			if ($LOGdelete_user_groups > 0) {
				echo "<a href=\"$PHP_SELF?ADD=511111&user_group=$user_group\" class='btn_dark'>" . _QXZ("DELETE THIS USER GROUP") . "</a>\n";
			}
			if (($LOGuser_level >= 9) and ((preg_match("/Administration Change Log/", $LOGallowed_reports)) or (preg_match("/ALL REPORTS/", $LOGallowed_reports)))) {
				echo "<a href=\"$PHP_SELF?ADD=720000000000000&category=USERGROUPS&stage=$user_group\" style='display:none;'>" . _QXZ("Click here to see Admin changes to this user group") . "</a>\n";
			}
		}
	} else {
		echo "<div class='error_popup'>" . _QXZ("You do not have permission to view this page") . "</div>\n";
		exit;
	}
}


