			echo "<div class='did_label_input'><label style='width: 34%;'>" . _QXZ("IP List") . ": </label><span>$ip_list_id</span></div>\n";
			echo "<div class='did_label_input'><label style='width: 34%;'>" . _QXZ("IP List Name") . ": </label><input type=text name=ip_list_name size=45 maxlength=100 value=\"$ip_list_name\"> $NWB#ip_lists-ip_list_name$NWE</div>\n";
			echo "<div class='did_label_input'><label style='width: 34%;'>" . _QXZ("Active") . ": </label><div class='custom-select' style='width:54%;'><select size=1 name=active>\n";
			echo "<option value=\"Y\">" . _QXZ("YES") . "</option>\n";
			echo "<option value=\"N\">" . _QXZ("NO") . "</option>\n";
			echo "<option value=\"$active\" SELECTED>" . _QXZ("$active") . "</option>\n";
			echo "</select></div>$NWB#ip_lists-active$NWE</div>\n";
			echo "<div class='did_label_input'><label style='width: 34%;'>" . _QXZ("Admin User Group") . ": </label><div class='custom-select' style='width:54%;'><select size=1 name=user_group>\n";
			echo "$UUgroups_list";
