			echo "</select></div>$NWB#ip_lists-user_group$NWE</div>\n";
			echo "<div class='did_label_input'><label style='width: 34%;'>" . _QXZ("IP Addresses") . ": </label><TEXTAREA name=ip_address ROWS=8 COLS=42>$vaf_textarea</TEXTAREA>$NWB#ip_lists-ip_address$NWE</div>\n";
			echo "</div>";
