		}

		echo "<script language=\"JavaScript\">\n";
		echo "var method_selected=0;\n";
		echo "\n";
		echo "function code_2FA(temp_method)\n";
		echo "	{\n";
		echo "	if (method_selected < 1)\n";
		echo "		{\n";
		echo "	    document.userform.stage.value = 'SUBMIT';\n";
