					    </div>";

		$agent_dead = 0;
		$agent_incall = 0;
		$agent_paused = 0;
		$agent_ready = 0;

		// 1. Get DEAD calls count
		$stmt_dead = "SELECT COUNT(*) AS dead_count
								FROM vicidial_live_agents vla
								LEFT JOIN vicidial_auto_calls vac
								    ON vac.callerid = vla.callerid
								WHERE vla.status = 'INCALL'
								AND (
								        vac.callerid IS NULL
								        OR vac.status IN ('DEAD','DROP','HUNGUP')
								    )
								AND UNIX_TIMESTAMP(vla.last_state_change) > UNIX_TIMESTAMP(NOW()) - 21600;";

		$rslt = mysql_to_mysqli($stmt_dead, $link);
		if ($row = mysqli_fetch_assoc($rslt)) {
			$agent_dead = $row['dead_count'];
		}

		// 2. Get INCALL agents count
		$stmt_incall = "SELECT COUNT(*) as incall_count 
						                FROM vicidial_live_agents 
						                WHERE status IN ('INCALL', 'QUEUE', 'PARK')
						                OR (status = 'PAUSED' AND lead_id > 0)";

		$rslt = mysql_to_mysqli($stmt_incall, $link);
		if ($row = mysqli_fetch_assoc($rslt)) {
			$agent_incall = $row['incall_count'];
		}

		// 3. Get PAUSED agents count
		$stmt_paused = "SELECT COUNT(*) as paused_count 
						                FROM vicidial_live_agents 
						                WHERE status = 'PAUSED'
						                AND lead_id = 0
						                AND UNIX_TIMESTAMP(last_state_change) > UNIX_TIMESTAMP(NOW()) - 21600";

		$rslt = mysql_to_mysqli($stmt_paused, $link);
		if ($row = mysqli_fetch_assoc($rslt)) {
			$agent_paused = $row['paused_count'];
		}

		// 4. Get READY agents count (agents waiting for calls)
		$stmt_ready = "SELECT COUNT(*) as ready_count 
						               FROM vicidial_live_agents 
						               WHERE status IN ('READY', 'CLOSER')";

		$rslt = mysql_to_mysqli($stmt_ready, $link);
		if ($row = mysqli_fetch_assoc($rslt)) {
			$agent_ready = $row['ready_count'];
		}

