					            document.getElementById('ready-count').innerText = data.agent_ready;
					            document.getElementById('incall-count').innerText = data.agent_incall;
					            document.getElementById('paused-count').innerText = data.agent_paused;
					        })
					        .catch(error => {
					            console.error('Error:', error);
					        });
					}

					// Call immediately and then every 5 seconds
					updateAgentStats();
					setInterval(updateAgentStats, 5000);
